import consola from "consola"

import { state } from "~/lib/state"
import { cacheModels } from "~/lib/utils"

/**
 * Upstream serves /models with `cache-control: private, max-age=21600`, so a
 * six-hour cadence matches the provider's own expectation for how long a
 * catalog snapshot stays valid.
 */
export const DEFAULT_CATALOG_REFRESH_MS = 6 * 60 * 60 * 1000

type CatalogUpdater = () => Promise<void>

interface CatalogSchedulerOptions {
  /** Refresh cadence in milliseconds. Zero or negative disables refresh. */
  intervalMs?: number
  updater?: CatalogUpdater
}

let refreshPromise: Promise<void> | undefined
let refreshTimer: ReturnType<typeof setTimeout> | undefined
let catalogUpdater: CatalogUpdater = cacheModels
let refreshIntervalMs = DEFAULT_CATALOG_REFRESH_MS
let shuttingDown = false
let shutdownHandlersInstalled = false

function currentModelIds(): Array<string> {
  return (state.models?.data ?? []).map((model) => model.id)
}

/**
 * Adopting a catalog change silently would move requests between the native
 * Responses, Responses-translation and Chat paths with no operator signal, so
 * every routing-relevant change is named explicitly.
 */
function reportCatalogChange(
  previousIds: Array<string>,
  previousFingerprint: string | undefined,
): void {
  if (state.modelsFingerprint === previousFingerprint) return

  const nextIds = currentModelIds()
  const previous = new Set(previousIds)
  const next = new Set(nextIds)
  const added = nextIds.filter((id) => !previous.has(id))
  const removed = previousIds.filter((id) => !next.has(id))

  consola.info(
    `Copilot catalog changed (${nextIds.length} models): added [${
      added.join(", ") || "none"
    }], removed [${removed.join(", ") || "none"}]`,
  )
}

function refreshCatalog(): Promise<void> {
  refreshPromise ??= (() => {
    const previousIds = currentModelIds()
    const previousFingerprint = state.modelsFingerprint
    return catalogUpdater()
      .then(() => {
        reportCatalogChange(previousIds, previousFingerprint)
      })
      .catch((error: unknown) => {
        consola.warn(
          "Failed to refresh Copilot model catalog; keeping the previous snapshot:",
          error,
        )
      })
      .finally(() => {
        refreshPromise = undefined
      })
  })()
  return refreshPromise
}

function scheduleNextRefresh(): void {
  if (shuttingDown || refreshIntervalMs <= 0) return
  refreshTimer = setTimeout(() => {
    void refreshCatalog().finally(scheduleNextRefresh)
  }, refreshIntervalMs)
  refreshTimer.unref()
}

/**
 * Starts periodic catalog refresh. The startup snapshot is already loaded by
 * `cacheModels()`, so this only schedules subsequent refreshes.
 */
export function startCatalogScheduler(
  options: CatalogSchedulerOptions = {},
): void {
  shuttingDown = false
  refreshIntervalMs = options.intervalMs ?? DEFAULT_CATALOG_REFRESH_MS
  catalogUpdater = options.updater ?? cacheModels

  if (refreshIntervalMs <= 0) {
    consola.info(
      "Copilot catalog refresh disabled; pinning the startup snapshot",
    )
    return
  }

  if (!refreshTimer) scheduleNextRefresh()

  if (!shutdownHandlersInstalled) {
    shutdownHandlersInstalled = true
    for (const signal of ["SIGINT", "SIGTERM"] as const) {
      process.once(signal, stopCatalogScheduler)
    }
  }
}

export function stopCatalogScheduler(): void {
  shuttingDown = true
  if (refreshTimer) clearTimeout(refreshTimer)
  refreshTimer = undefined
}

/** Triggers a refresh immediately, sharing any refresh already in flight. */
export function refreshCatalogNow(): Promise<void> {
  return refreshCatalog()
}

import { afterEach, beforeEach, describe, expect, it } from "bun:test"

import type { ModelsResponse } from "~/services/copilot/get-models"

import { catalogFingerprint } from "~/lib/build-info"
import { state } from "~/lib/state"
import {
  DEFAULT_CATALOG_REFRESH_MS,
  refreshCatalogNow,
  startCatalogScheduler,
  stopCatalogScheduler,
} from "~/services/copilot/catalog-scheduler"

function catalog(ids: Array<string>): ModelsResponse {
  return {
    object: "list",
    data: ids.map((id) => ({
      id,
      name: id,
      object: "model",
      vendor: "openai",
      version: "1",
      preview: false,
      model_picker_enabled: true,
      supported_endpoints: ["/responses"],
      capabilities: {
        family: "gpt",
        limits: {},
        object: "model_capabilities",
        supports: {},
        tokenizer: "test",
        type: "chat",
      },
    })),
  }
}

/** Mirrors what cacheModels() does, without touching the network. */
function applyCatalog(ids: Array<string>): void {
  const models = catalog(ids)
  state.models = models
  state.modelsObservedAt = new Date().toISOString()
  state.modelsFingerprint = catalogFingerprint(models.data)
}

beforeEach(() => {
  applyCatalog(["gpt-a"])
})

afterEach(() => {
  stopCatalogScheduler()
  state.models = undefined
  state.modelsFingerprint = undefined
  state.modelsObservedAt = undefined
})

describe("catalog scheduler", () => {
  it("matches the upstream six hour cache hint by default", () => {
    expect(DEFAULT_CATALOG_REFRESH_MS).toBe(21_600_000)
  })

  it("does not refresh on start, preserving the startup snapshot", () => {
    let calls = 0
    startCatalogScheduler({
      intervalMs: 60_000,
      updater: () => {
        calls += 1
        return Promise.resolve()
      },
    })
    expect(calls).toBe(0)
  })

  it("replaces the snapshot and updates both provenance markers", async () => {
    const before = state.modelsFingerprint
    const observedBefore = state.modelsObservedAt

    startCatalogScheduler({
      intervalMs: 60_000,
      updater: () => {
        applyCatalog(["gpt-a", "gpt-b"])
        return Promise.resolve()
      },
    })
    await Bun.sleep(2)
    await refreshCatalogNow()

    expect(state.models?.data).toHaveLength(2)
    expect(state.modelsFingerprint).not.toBe(before)
    expect(state.modelsObservedAt).not.toBe(observedBefore)
  })

  it("refreshes the observation timestamp even when content is identical", async () => {
    const fingerprintBefore = state.modelsFingerprint
    const observedBefore = state.modelsObservedAt

    startCatalogScheduler({
      intervalMs: 60_000,
      updater: () => {
        applyCatalog(["gpt-a"])
        return Promise.resolve()
      },
    })
    await Bun.sleep(2)
    await refreshCatalogNow()

    expect(state.modelsFingerprint).toBe(fingerprintBefore)
    expect(state.modelsObservedAt).not.toBe(observedBefore)
  })

  it("keeps the previous snapshot when a refresh fails", async () => {
    const fingerprintBefore = state.modelsFingerprint

    startCatalogScheduler({
      intervalMs: 60_000,
      updater: () => Promise.reject(new Error("offline")),
    })
    await refreshCatalogNow()

    expect(state.models?.data).toHaveLength(1)
    expect(state.modelsFingerprint).toBe(fingerprintBefore)
  })

  it("does not reject the caller when a refresh fails", async () => {
    let rejected = false
    startCatalogScheduler({
      intervalMs: 60_000,
      updater: () => Promise.reject(new Error("offline")),
    })
    try {
      await refreshCatalogNow()
    } catch {
      rejected = true
    }
    expect(rejected).toBe(false)
  })

  it("recovers on the next refresh after a failure", async () => {
    let shouldFail = true
    startCatalogScheduler({
      intervalMs: 60_000,
      updater: () => {
        if (shouldFail) return Promise.reject(new Error("offline"))
        applyCatalog(["gpt-a", "gpt-c"])
        return Promise.resolve()
      },
    })

    await refreshCatalogNow()
    expect(state.models?.data).toHaveLength(1)

    shouldFail = false
    await refreshCatalogNow()
    expect(state.models?.data).toHaveLength(2)
  })

  it("shares a single in-flight refresh across concurrent triggers", async () => {
    let calls = 0
    let release: (() => void) | undefined
    startCatalogScheduler({
      intervalMs: 60_000,
      updater: () => {
        calls += 1
        return new Promise<void>((resolve) => {
          release = resolve
        })
      },
    })

    const triggers = [refreshCatalogNow(), refreshCatalogNow()]
    expect(calls).toBe(1)
    if (!release) throw new Error("Expected a pending refresh")
    release()
    await Promise.all(triggers)

    expect(calls).toBe(1)
  })

  it("never schedules a refresh when the interval is zero", async () => {
    let calls = 0
    startCatalogScheduler({
      intervalMs: 0,
      updater: () => {
        calls += 1
        return Promise.resolve()
      },
    })

    await Bun.sleep(20)
    expect(calls).toBe(0)
  })

  it("refreshes on the configured interval", async () => {
    let calls = 0
    startCatalogScheduler({
      intervalMs: 5,
      updater: () => {
        calls += 1
        applyCatalog(["gpt-a"])
        return Promise.resolve()
      },
    })

    await Bun.sleep(60)
    expect(calls).toBeGreaterThan(0)
  })

  it("stops refreshing once the scheduler is stopped", async () => {
    let calls = 0
    startCatalogScheduler({
      intervalMs: 5,
      updater: () => {
        calls += 1
        return Promise.resolve()
      },
    })

    await Bun.sleep(40)
    stopCatalogScheduler()
    const callsAtStop = calls

    await Bun.sleep(40)
    expect(calls).toBe(callsAtStop)
  })
})

#!/usr/bin/env node

import { defineCommand } from "citty"
import clipboard from "clipboardy"
import consola from "consola"
import { serve, type ServerHandler } from "srvx"
import invariant from "tiny-invariant"

import { ensurePaths } from "./lib/paths"
import { initProxyFromEnv } from "./lib/proxy"
import { generateEnvScript } from "./lib/shell"
import { state } from "./lib/state"
import { setupCopilotToken, setupGitHubToken } from "./lib/token"
import { cacheModels, cacheVSCodeVersion } from "./lib/utils"
import { server } from "./server"
import { startCatalogScheduler } from "./services/copilot/catalog-scheduler"
import { startPricingScheduler } from "./services/copilot/pricing-scheduler"

interface RunServerOptions {
  port: number
  verbose: boolean
  accountType: string
  manual: boolean
  rateLimit?: number
  rateLimitWait: boolean
  githubToken?: string
  claudeCode: boolean
  showToken: boolean
  proxyEnv: boolean
  hideInternal: boolean
  modelFilter?: string
  catalogRefreshMinutes: number
}

export async function runServer(options: RunServerOptions): Promise<void> {
  if (options.proxyEnv) {
    initProxyFromEnv()
  }

  if (options.verbose) {
    consola.level = 5
    consola.info("Verbose logging enabled")
  }

  state.accountType = options.accountType
  if (options.accountType !== "individual") {
    consola.info(`Using ${options.accountType} plan GitHub account`)
  }

  state.manualApprove = options.manual
  state.rateLimitSeconds = options.rateLimit
  state.rateLimitWait = options.rateLimitWait
  state.showToken = options.showToken
  state.hideInternal = options.hideInternal
  state.modelFilter = options.modelFilter

  await ensurePaths()
  await cacheVSCodeVersion()

  if (options.githubToken) {
    state.githubToken = options.githubToken
    consola.info("Using provided GitHub token")
  } else {
    await setupGitHubToken()
  }

  await setupCopilotToken()
  await cacheModels()
  startCatalogScheduler({ intervalMs: options.catalogRefreshMinutes * 60_000 })
  await startPricingScheduler()

  const modelCount = state.models?.data.length ?? 0
  consola.info(
    `Available models (${modelCount} loaded): \n${state.models?.data.map((model) => `- ${model.id}`).join("\n")}`,
  )

  const serverUrl = `http://localhost:${options.port}`

  // Detect 1M context from ANTHROPIC_MODEL env var (set before proxy starts)
  const anthropicModelEnv = process.env.ANTHROPIC_MODEL ?? ""
  const is1MFromEnv =
    anthropicModelEnv.includes("[1m]") || anthropicModelEnv.endsWith("-1m")
  if (is1MFromEnv) {
    state.is1MContext = true
    consola.info("1M context window mode enabled (from ANTHROPIC_MODEL)")
  }

  if (options.claudeCode) {
    invariant(state.models, "Models should be loaded by now")

    const selectedModel = await consola.prompt(
      "Select a model to use with Claude Code",
      {
        type: "select",
        options: state.models.data.map((model) => model.id),
      },
    )

    // Detect 1M context from interactive selection

    state.is1MContext = state.is1MContext || selectedModel.endsWith("-1m")
    if (selectedModel.endsWith("-1m")) {
      consola.info("1M context window mode enabled (from model selection)")
    }

    const selectedSmallModel = await consola.prompt(
      "Select a small model to use with Claude Code",
      {
        type: "select",
        options: state.models.data.map((model) => model.id),
      },
    )

    const command = generateEnvScript(
      {
        ANTHROPIC_BASE_URL: serverUrl,
        ANTHROPIC_AUTH_TOKEN: "dummy",
        ANTHROPIC_MODEL: selectedModel,
        ANTHROPIC_DEFAULT_SONNET_MODEL: selectedModel,
        ANTHROPIC_SMALL_FAST_MODEL: selectedSmallModel,
        ANTHROPIC_DEFAULT_HAIKU_MODEL: selectedSmallModel,
        DISABLE_NON_ESSENTIAL_MODEL_CALLS: "1",
        CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC: "1",
      },
      "claude",
    )

    try {
      clipboard.writeSync(command)
      consola.success("Copied Claude Code command to clipboard!")
    } catch {
      consola.warn(
        "Failed to copy to clipboard. Here is the Claude Code command:",
      )
      consola.log(command)
    }
  }

  consola.box(
    `🌐 Usage Viewer: https://ericc-ch.github.io/copilot-api?endpoint=${serverUrl}/usage`,
  )

  const instance = serve({
    fetch: server.fetch as ServerHandler,
    port: options.port,
  })
  if (process.env.NODE_ENV !== "production") {
    process.once("SIGINT", async () => {
      await instance.close(true)
      process.exit(0)
    })
  }
}

export const start = defineCommand({
  meta: {
    name: "start",
    description: "Start the Copilot API server",
  },
  args: {
    port: {
      alias: "p",
      type: "string",
      default: "4141",
      description: "Port to listen on",
    },
    verbose: {
      alias: "v",
      type: "boolean",
      default: false,
      description: "Enable verbose logging",
    },
    "account-type": {
      alias: "a",
      type: "string",
      default: "individual",
      description: "Account type to use (individual, business, enterprise)",
    },
    manual: {
      type: "boolean",
      default: false,
      description: "Enable manual request approval",
    },
    "rate-limit": {
      alias: "r",
      type: "string",
      description: "Rate limit in seconds between requests",
    },
    wait: {
      alias: "w",
      type: "boolean",
      default: false,
      description:
        "Wait instead of error when rate limit is hit. Has no effect if rate limit is not set",
    },
    "github-token": {
      alias: "g",
      type: "string",
      description:
        "Provide GitHub token directly (must be generated using the `auth` subcommand)",
    },
    "claude-code": {
      alias: "c",
      type: "boolean",
      default: false,
      description:
        "Generate a command to launch Claude Code with Copilot API config",
    },
    "show-token": {
      type: "boolean",
      default: false,
      description: "Show GitHub and Copilot tokens on fetch and refresh",
    },
    "proxy-env": {
      type: "boolean",
      default: false,
      description: "Initialize proxy from environment variables",
    },
    "hide-internal": {
      type: "boolean",
      default: false,
      description:
        "Hide internal and account-scoped models from the /models response",
    },
    "model-filter": {
      type: "string",
      description:
        "Filter /models response to only show models from a specific vendor (e.g. anthropic, openai)",
    },
    "catalog-refresh-minutes": {
      type: "string",
      default: "360",
      description:
        "Minutes between model catalog refreshes (default 360, matching the upstream 6h cache hint). Use 0 to pin the startup snapshot",
    },
  },
  run({ args }) {
    const rateLimitRaw = args["rate-limit"]
    const rateLimit =
      // eslint-disable-next-line @typescript-eslint/no-unnecessary-condition
      rateLimitRaw === undefined ? undefined : Number.parseInt(rateLimitRaw, 10)

    const catalogRefreshRaw = Number.parseInt(
      args["catalog-refresh-minutes"],
      10,
    )
    const catalogRefreshMinutes =
      Number.isNaN(catalogRefreshRaw) || catalogRefreshRaw < 0 ?
        360
      : catalogRefreshRaw

    return runServer({
      port: Number.parseInt(args.port, 10),
      verbose: args.verbose,
      accountType: args["account-type"],
      manual: args.manual,
      rateLimit,
      rateLimitWait: args.wait,
      githubToken: args["github-token"],
      claudeCode: args["claude-code"],
      showToken: args["show-token"],
      proxyEnv: args["proxy-env"],
      hideInternal: args["hide-internal"],
      modelFilter: args["model-filter"],
      catalogRefreshMinutes,
    })
  },
})
